    pattern_w double precision NOT NULL,
    institutional_w double precision NOT NULL,
    regime_w double precision NOT NULL,
    threshold double precision DEFAULT 0.35 NOT NULL,
    sample_size integer,
    signal_quality_mean double precision,
    created_at timestamp with time zone DEFAULT now(),
    asset_cluster text DEFAULT 'global'::text NOT NULL,
    weights jsonb DEFAULT '{}'::jsonb,
