--
-- Name: contract_metadata; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contract_metadata (
    symbol text NOT NULL,
    base_symbol text NOT NULL,
    asset_class text NOT NULL,
    expiry_date timestamp with time zone,
    first_notice_date timestamp with time zone,
    roll_from text,
    roll_to text,
    roll_date timestamp with time zone,
    roll_gap double precision,
    exchange text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    is_front_month boolean DEFAULT false,
    roll_direction character varying(10) DEFAULT 'unknown'::character varying,
    roll_detected_at timestamp with time zone DEFAULT now(),
    confirmation_count integer DEFAULT 0,
    CONSTRAINT contract_metadata_asset_class_check CHECK ((asset_class = ANY (ARRAY['futures'::text, 'equity'::text, 'crypto'::text, 'fx'::text, 'option'::text]))),
    CONSTRAINT contract_metadata_roll_direction_check CHECK (((roll_direction)::text = ANY (ARRAY[('up'::character varying)::text, ('down'::character varying)::text, ('flat'::character varying)::text, ('unknown'::character varying)::text])))
);


--
-- Name: TABLE contract_metadata; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.contract_metadata IS 'Futures contract roll tracking. Each row is a single contract with roll chain links.';


--
-- Name: COLUMN contract_metadata.symbol; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.symbol IS 'Contract symbol (e.g., "ESH6") - primary key';


--
-- Name: COLUMN contract_metadata.base_symbol; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.base_symbol IS 'Base symbol grouping (e.g., "ES") for roll chain navigation';


--
-- Name: COLUMN contract_metadata.asset_class; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.asset_class IS 'Asset class (futures, equity, crypto, fx, option)';


--
-- Name: COLUMN contract_metadata.expiry_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.expiry_date IS 'Contract expiration date';


--
-- Name: COLUMN contract_metadata.first_notice_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.first_notice_date IS 'First notice date - last day to close position without assignment';


--
-- Name: COLUMN contract_metadata.roll_from; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_from IS 'Previous contract in roll chain (NULL for oldest)';


--
-- Name: COLUMN contract_metadata.roll_to; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_to IS 'Next contract in roll chain (NULL for current front-month)';


--
-- Name: COLUMN contract_metadata.roll_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_date IS 'Date this contract became active front-month';


--
-- Name: COLUMN contract_metadata.roll_gap; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_gap IS 'Price adjustment at roll (close of previous vs open of current)';


--
-- Name: COLUMN contract_metadata.exchange; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.exchange IS 'Exchange name (e.g., CME, NYMEX, COMEX)';


--
-- Name: COLUMN contract_metadata.is_front_month; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.is_front_month IS 'True when this contract is the current active front-month';


--
-- Name: COLUMN contract_metadata.roll_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_direction IS 'Price direction at roll boundary: up / down / flat / unknown';


--
-- Name: COLUMN contract_metadata.roll_detected_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.roll_detected_at IS 'Timestamp when automated roll monitor detected this roll';


--
-- Name: COLUMN contract_metadata.confirmation_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_metadata.confirmation_count IS 'Number of consecutive bars that confirmed the volume-based roll signal';


