COMMENT ON COLUMN public.system_events.roll_gap IS 'Absolute price gap at roll boundary (close_old vs open_new)';


--
-- Name: COLUMN system_events.roll_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_events.roll_direction IS 'Roll price direction: up / down / flat / unknown';


--
-- Name: COLUMN system_events.event_data; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.system_events.event_data IS 'Arbitrary JSON payload for extensibility (z_score, confirmation_bars, etc.)';


--
-- Name: system_events_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.system_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: system_events_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.system_events_id_seq OWNED BY public.system_events.id;


--
-- Name: tod_multipliers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tod_multipliers (
    regime_type text NOT NULL,
    tf text NOT NULL,
    hour_et smallint NOT NULL,
    multiplier double precision NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    symbol text DEFAULT '*'::text NOT NULL,
    CONSTRAINT tod_multipliers_hour_et_check CHECK (((hour_et >= 0) AND (hour_et <= 23)))
);


--
-- Name: transform_graduation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transform_graduation (
    transform_id text NOT NULL,
    transform_version text NOT NULL,
    segment_key text NOT NULL,
    n integer NOT NULL,
    spearman_rho double precision,
    spearman_p double precision,
    calibration_max_error double precision,
    cvar_bottom_decile double precision,
    mde double precision,
    val_rho double precision,
    overfitting_risk boolean,
    sharpe_delta double precision,
    is_graduated boolean DEFAULT false NOT NULL,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL
);


--
-- Name: TABLE transform_graduation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.transform_graduation IS 'Phase 72: per-segment Renaissance-grade graduation evidence. Not a hypertable.';


--
-- Name: COLUMN transform_graduation.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transform_graduation.expires_at IS 'evaluated_at + 90 days. Graduation must re-prove each quarter.';


